import EditableForm from "./EditableForm";
import { getAllWorkshops, getWorkshopById, updateWorkshopById } from "../services/workshopService";
import { useState, useEffect } from "react";
import {
    Card,
    CardContent,
    Grid,
    Stack,
    Typography,
} from "@mui/material";
import LocationOnIcon from "@mui/icons-material/LocationOn";
import CalendarMonthIcon from "@mui/icons-material/CalendarMonth";
import AccessTimeIcon from "@mui/icons-material/AccessTime";

// ********************************************
// Mostly generated by ChatGPT
// *********************************************
export default function WorkshopEditor() {
 const [allWorkshops, setAllWorkshops] = useState([]);

      useEffect(() => {
          let ignore = false;
  
          async function load() {
            
              // API calls: workshop fetch
              const response = await getAllWorkshops();

              if (!ignore) {
                setAllWorkshops(response);
                
              }
          }
          
          load().catch(console.error);

          return () => {
              ignore = true;
          };
      }, []);


    async function handleSave(id, newWorkshop) {
        await updateWorkshopById(id, newWorkshop);

        setAllWorkshops((previous) =>
            previous.map((workshop) =>
            workshop.id === id ? { ...workshop, ...newWorkshop } : workshop
            )
        );
    }

      return (
        <div style={{
            overflowY: 'auto',
            maxHeight: '800px'
        }}>
            
             {!allWorkshops || allWorkshops === null ? "No workshops to edit." : allWorkshops.map((workshop) => (
                 <Grid key={workshop.id} size={{ xs: 12, md: 6 }}>
                    <Card variant="outlined" sx={{ height: "100%" }}>
                         <CardContent>
                            <h4>{workshop.title}</h4>

                            <Stack spacing={2} sx={{ mb: 3 }}>
                            {/* Location */}
                            <Stack direction="row" spacing={1}>
                              <LocationOnIcon color="primary" aria-hidden="true" />
                                <Typography>{workshop.address}</Typography>
                            </Stack>

                                                    {/* Date */}
                                                    <Stack direction="row" spacing={1}>
                                                        <CalendarMonthIcon color="primary" aria-hidden="true" />
                                                        <Typography>{workshop.date}</Typography>
                                                    </Stack>

                                                    {/* Time */}
                                                    <Stack direction="row" spacing={1}>
                                                        <AccessTimeIcon color="primary" aria-hidden="true" />
                                                        <Typography>{workshop.time}</Typography>
                                                    </Stack>

                                                    {/* Event Type */}
                                                    <Typography>
                                                        <strong>Type:</strong> {workshop.eventType}
                                                    </Typography>

                                                    {/* Distance */}
                                                    {workshop.eventType !== "Virtual" && (
                                                        <Typography>
                                                            <strong>Distance:</strong> {workshop.distanceMiles} miles
                                                        </Typography>
                                                    )}
                                                </Stack>                     
                    <EditableForm
                        key={workshop.id}
                        fields={[
                            { name: "title", label: "Title", required: true },
                            { name: "location", label: "Location", required: true},
                            { name: "dateTime", label: "Date & Time", required: true, type: "datetime-local"},
                            { name: "roomNumber", label: "Room Number", required: true },
                            { name: "instructorName", label: "Instructor Name", required: true },
                            { name: "accessibilityFeatures", label: "AccessibilityFeatures", required: false},
                            { name: "seatAvailability", label: "Seat Availability", required: true }
                        ]}
                        onLoad={async () => await getWorkshopById(workshop.id)}
                        onSave={async(newWorkshop) => {
                            return await handleSave(workshop.id, newWorkshop);
                        }
                    }/>
                     </CardContent>
                    </Card>
                </Grid>
            
             ))}
             </div>
            )
            }

            
        

            


